 71	    Result primMST(int[][] graph) {
 72	        validateGraph(graph);
 73	
 74	        int vertexCount = graph.length;
 75	        int[] parent = new int[vertexCount];
 76	        int[] key = new int[vertexCount];
 77	        boolean[] includedInMst = new boolean[vertexCount];
 78	
 79	        Arrays.fill(key, Integer.MAX_VALUE);
 80	        key[0] = 0;
 81	        parent[0] = -1;
 82	
 83	        for (int count = 0; count < vertexCount - 1; count++) {
 84	            int currentVertex = selectNextVertex(key, includedInMst);
 85	
 86	            if (currentVertex == -1) {
 87	                throw new IllegalStateException("Graph must be connected.");
 88	            }
 89	
 90	            includedInMst[currentVertex] = true;
 91	
 92	            for (int neighbor = 0; neighbor < vertexCount; neighbor++) {
 93	                int edgeWeight = graph[currentVertex][neighbor];
 94	
 95	                if (edgeWeight != NO_EDGE && !includedInMst[neighbor]
 96	                    && edgeWeight < key[neighbor]) {
 97	                    parent[neighbor] = currentVertex;
 98	                    key[neighbor] = edgeWeight;
 99	                }
100	            }
101	        }
102	
103	        return buildResult(parent, graph);
104	    }
